"""Apply an RFC 7386 JSON Merge Patch."""

import json
import sys


def merge_patch(target, patch):
    if not isinstance(patch, dict):
        return patch
    result = dict(target) if isinstance(target, dict) else {}
    for key, value in patch.items():
        if value is None:
            result.pop(key, None)
        else:
            result[key] = merge_patch(result.get(key), value)
    return result


def load(path):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)
    except OSError as exc:
        sys.stderr.write("cannot read %s: %s\n" % (path, exc.strerror or exc))
        raise SystemExit(1)
    except ValueError as exc:
        sys.stderr.write("invalid JSON in %s: %s\n" % (path, exc))
        raise SystemExit(1)


def main(argv):
    if len(argv) != 3:
        sys.stderr.write("usage: merge_patch.py <target.json> <patch.json>\n")
        return 2
    target = load(argv[1])
    patch = load(argv[2])
    json.dump(merge_patch(target, patch), sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
